function graph(title,vertical,horizontal){google.charts.load("current",{packages:["corechart"],language:"nl"});google.charts.setOnLoadCallback(function(){drawChart(title,vertical,horizontal)})}function drawChart(title,vertical,horizontal){let jsonData=$("#curveData").data("chart");if(Object.keys(jsonData).length===0){jsonData=[1906,0,0]}let data=new google.visualization.DataTable;if(jsonData.length===365){data.addColumn("date","x")}else{data.addColumn("number","x")}data.addColumn("number","y");data.addColumn("number","y glad");jsonData.forEach(function(element,index){if(jsonData.length===365){let date=new Date("December 31, 2024");date.setDate(date.getDate()+jsonData[index][0]);data.addRow([date,jsonData[index][1],jsonData[index][2]])}else{data.addRow([jsonData[index][0],jsonData[index][1],jsonData[index][2]])}});let options={title:title,curveType:"function",vAxis:{title:vertical},legend:{position:"none"}};if(jsonData.length===365){options["hAxis"]={title:horizontal,format:"MMM-dd"}}else{options["hAxis"]={title:horizontal}}let chart=new google.visualization.LineChart(document.getElementById("curve_chart"));chart.draw(data,options)}if($("#curve_chart").length>0){graph($("#graph-title").val(),$("#graph-vertical").val(),$("#graph-horizontal").val())}if($("#id_component").val()!==""){$([document.documentElement,document.body]).animate({scrollTop:$("#textOutput").offset().top},2e3)}